import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, addLine } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { invoiceTotals } from '../src/invoices.js';

test('statement returns invoices for a valid customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued1], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement includes invoice number and dates', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued1], '2025-10-10');
  const invoice = result.value.invoices[0];

  assert.equal(invoice.number, issued1.number);
  assert.equal(invoice.issueDate, '2025-10-07');
  assert.equal(invoice.dueDate, '2025-11-06');
});

test('statement includes total and due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued1], '2025-10-10');
  const invoice = result.value.invoices[0];
  const expectedTotal = invoiceTotals(issued1).total;
  const expectedDue = balanceDue(issued1);

  assert.equal(invoice.total, expectedTotal);
  assert.equal(invoice.due, expectedDue);
});

test('statement reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-999', [issued1], '2025-10-10');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement filters out draft invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = statement('C-001', [inv1], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes issued invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued1], '2025-10-10');
  assert.equal(result.value.invoices.length, 1);
});

test('statement includes partially_paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const totals = invoiceTotals(issued1);
  const partialPaid = recordPayment(issued1, { amount: totals.total - 1000, date: '2025-10-08' }).value;

  const result = statement('C-001', [partialPaid], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 1000);
});

test('statement filters out paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const totals = invoiceTotals(issued1);
  const paid = recordPayment(issued1, { amount: totals.total, date: '2025-10-08' }).value;

  const result = statement('C-001', [paid], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement filters by issueDate on or before asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  // asOf 2025-10-10 should include only inv1
  const result = statement('C-001', [issued1, issued2], '2025-10-10');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2025-10-07');
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued1], '2025-10-07');
  assert.equal(result.value.invoices.length, 1);
});

test('statement filters by customerId', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-10-10');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued1.number);
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const result = statement('C-001', [issued1, issued2, issued3], '2025-10-20');
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2025-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2025-10-10');
  assert.equal(result.value.invoices[2].issueDate, '2025-10-15');
});

test('statement calculates totalDue as sum of due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const due1 = balanceDue(issued1);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;
  const due2 = balanceDue(issued2);

  const result = statement('C-001', [issued1, issued2], '2025-10-15');
  assert.equal(result.value.totalDue, due1 + due2);
});

test('statement with empty invoice list', () => {
  const result = statement('C-001', [], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement with partially paid invoices shows correct due', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const totals = invoiceTotals(issued1);
  const payment = recordPayment(issued1, { amount: 5000, date: '2025-10-08' }).value;

  const result = statement('C-001', [payment], '2025-10-10');
  const invoice = result.value.invoices[0];

  assert.equal(invoice.total, totals.total);
  assert.equal(invoice.due, totals.total - 5000);
});

test('statement normalizes customer ID', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = statement('c-001', [issued1], '2025-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement with multiple customers and filters correctly', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const result = statement('C-001', [issued1, issued2, issued3], '2025-10-10');
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].number, issued1.number);
  assert.equal(result.value.invoices[1].number, issued3.number);
});

test('statement with invoices having different VAT rates', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-08',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-10-10');
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].total, invoiceTotals(issued1).total);
  assert.equal(result.value.invoices[1].total, invoiceTotals(issued2).total);
});

test('statement with large number of invoices', () => {
  const allInvoices = [];
  for (let i = 0; i < 20; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2025-01-${String(i + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    const issued = issueInvoice(inv, allInvoices.map((x) => x.number).filter((n) => n)).value;
    allInvoices.push(issued);
  }

  const result = statement('C-001', allInvoices, '2025-01-15');
  assert.equal(result.value.invoices.length, 15);
  const dueDates = result.value.invoices.map((inv) => inv.issueDate);
  for (let i = 0; i < dueDates.length - 1; i++) {
    assert.ok(dueDates[i] <= dueDates[i + 1]);
  }
});

test('statement totalDue with mix of full and partial payments', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const totals1 = invoiceTotals(issued1);
  const paid1 = recordPayment(issued1, { amount: 3000, date: '2025-10-05' }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;
  const totals2 = invoiceTotals(issued2);

  const result = statement('C-001', [paid1, issued2], '2025-10-10');
  const expectedTotalDue = (totals1.total - 3000) + totals2.total;
  assert.equal(result.value.totalDue, expectedTotalDue);
});

